{
  "findings": [
    {
      "check_id": "CKV2_AWS_40",
      "title": "Ensure AWS IAM policy does not allow full IAM privileges",
      "resource": "aws_iam_user_policy_attachment.privesc3-passrole-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "The attached policy 'aws_iam_policy.fn1-passrole-star' may allow overly permissive actions (e.g., wildcard permissions). This can lead to privilege escalation or unintended access."
    }
  ],
  "patched_code": "resource "aws_iam_user_policy_attachment" "privesc3-passrole-user-attach-policy" {
  user       = aws_iam_user.fn1-privesc3-partial-user.name
  policy_arn = aws_iam_policy.fn1-passrole-limited.arn
}

resource "aws_iam_policy" "fn1-passrole-limited" {
  name        = "fn1-passrole-limited"
  description = "A more restrictive policy for PassRole"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "iam:PassRole",
      "Resource": "arn:aws:iam::123456789012:role/specific-role-name"
    }
  ]
}
EOF
}
",
  "fix_summary": "Replaced the overly permissive policy 'fn1-passrole-star' with a more restrictive policy 'fn1-passrole-limited' that limits the 'iam:PassRole' action to a specific role."
}
